/**
 * Differential golden test: `selectFeed` must reproduce square-hole-handoff/reference/feed_model.py `select()` for
 * every case generated by scripts/feed-golden.py (sort x search x kind x reward address).
 */
import { spawnSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { describe, expect, it } from 'vitest';
import { selectFeed, type AssetKind, type FeedSort } from './index';
import { HANDOFF_ROOT, REPO_ROOT, handoffFixture } from './test-support/handoff';

interface GoldenCase {
  id: string;
  sort: FeedSort;
  search: string;
  kind: 'all' | AssetKind;
  rewardAddress: string | null;
  platform: string | null;
  rows: string[];
}
interface Golden {
  caseCount: number;
  cases: GoldenCase[];
  fixtureSha256: string;
  referenceSha256: string;
}

const goldenText = readFileSync(fileURLToPath(new URL('./__golden__/feed-select.json', import.meta.url)), 'utf8');
const golden = JSON.parse(goldenText) as Golden;
const sha256 = (path: string): string => createHash('sha256').update(readFileSync(path)).digest('hex');

const probe = spawnSync('python3', ['--version'], { encoding: 'utf8' });
const hasPython = probe.error === undefined && probe.status === 0;

describe('selectFeed vs Python reference (golden)', () => {
  const items = handoffFixture().items;

  it('golden matches the current handoff fixture and reference model', () => {
    expect(golden.fixtureSha256).toBe(sha256(`${HANDOFF_ROOT}fixtures/feed.json`));
    expect(golden.referenceSha256).toBe(sha256(`${HANDOFF_ROOT}reference/feed_model.py`));
    expect(golden.cases).toHaveLength(golden.caseCount);
    expect(golden.caseCount).toBe(630);
  });

  it.each(golden.cases.map((c) => [c.id, c] as const))('%s', (_id, c) => {
    const { platform, rows } = selectFeed(items, {
      sort: c.sort,
      search: c.search,
      type: c.kind,
      rewardAddress: c.rewardAddress ?? undefined,
    });
    expect({ platform: platform?.pairId ?? null, rows: rows.map((row) => row.pairId) }).toEqual({ platform: c.platform, rows: c.rows });
  });

  it.skipIf(!hasPython)(
    hasPython
      ? 'committed golden is up to date (re-runs python3 scripts/feed-golden.py --stdout)'
      : 'committed golden is up to date — SKIPPED: python3 is not available on PATH',
    () => {
      const result = spawnSync('python3', ['scripts/feed-golden.py', '--stdout'], {
        cwd: REPO_ROOT,
        encoding: 'utf8',
        env: { ...process.env, PYTHONDONTWRITEBYTECODE: '1' },
        timeout: 60_000,
      });
      expect(result.status, result.stderr).toBe(0);
      expect(result.stdout).toBe(goldenText);
    },
  );
});
